export const ORIGIN='https://media-bank.fixture.test';
export const OWNER='fixture-owner-a';
export const COOKIE='fixture_media_session';
export const TOKEN='owner-a-test-session';
export function makeAssets(){return Array.from({length:241},(_,i)=>({id:`fixture-${String(i+1).padStart(3,'0')}`,filename:i===237?'ultraviolet-dragonfruit-238.jpg':`archive-${String(i+1).padStart(3,'0')}.${i%5===4?'mp4':'jpg'}`,storage_path:`${OWNER}/asset-${i+1}.${i%5===4?'mp4':'jpg'}`,file_type:i%5===4?'video/mp4':'image/jpeg',created_at:new Date(Date.UTC(2026,9,1,12)-i*60000).toISOString(),tags:[`subject:${i%3===0?'wood fired pizza':'garden event'}`,`person:${i%2?'Maya':'Jules'}`,...(i%7===0?['photographer:@fixture']:[])],ai_categories:[i%3===0?'Food':'Events'],user_id:OWNER}));}
export function queryAssets(assets,{q='',filter='all',offset=0,limit=24}={}){const term=q.trim().toLowerCase();const searched=assets.filter(a=>a.user_id===OWNER).filter(a=>!term||[a.filename,...a.tags,...a.ai_categories].some(v=>v.toLowerCase().includes(term)));const counts={all:searched.length,photo:searched.filter(a=>a.file_type.startsWith('image/')).length,video:searched.filter(a=>a.file_type.startsWith('video/')).length};const matching=searched.filter(a=>filter==='all'||a.file_type.startsWith(filter==='photo'?'image/':'video/'));const items=matching.slice(offset,offset+limit);return{items,total:matching.length,counts,hasMore:offset+items.length<matching.length,nextOffset:offset+items.length};}
export function assetSvg(id,original=false){const n=Number(id.replace(/\D/g,''))||1;const w=original?1200:320,h=original?900:240;const color=['#9b5f3f','#58786b','#b69a69','#556a83'][n%4];return `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 320 240"><rect width="320" height="240" fill="${color}"/><circle cx="${80+n%130}" cy="94" r="68" fill="#e7d7ae"/><circle cx="${80+n%130}" cy="94" r="54" fill="#cb7555"/><circle cx="${65+n%130}" cy="77" r="9" fill="#e9d6ac"/><circle cx="${106+n%130}" cy="102" r="13" fill="#557044"/><path d="M0 179 Q90 142 180 184 T320 170 V240 H0Z" fill="#292923"/><text x="16" y="216" fill="#fff7e8" font-family="sans-serif" font-size="17">${id}${original?' · original':''}</text></svg>`;}
